from collections import deque

def bfs_at_depth(graph, start, target_depth):
    """Find nodes at exactly target_depth from start node."""
    if target_depth == 0:
        return [start]

    visited = set([start])
    queue = deque([(start, 0)])
    depth_nodes = defaultdict(set)

    while queue:
        node, depth = queue.popleft()

        for neighbor in graph.get(node, []):
            if neighbor not in visited or depth + 1 == target_depth:
                new_depth = depth + 1
                if new_depth <= target_depth:
                    depth_nodes[new_depth].add(neighbor)
                    if new_depth < target_depth:
                        queue.append((neighbor, new_depth))
                        visited.add(neighbor)

    return sorted(list(depth_nodes.get(target_depth, [])))

# Perform BFS from 1679091c5a at depth 4
result = bfs_at_depth(graph, '1679091c5a', 4)
print(f"Nodes at depth 4: {result}")

# Let's also trace through each depth for verification
print("\nTracing BFS depths:")
for d in range(1, 5):
    nodes = bfs_at_depth(graph, '1679091c5a', d)
    print(f"Depth {d}: {nodes}")
```

